/**
 * The rule catalogue: one entry per rule, with what it means and how to fix
 * it, in the words a finding carries. The detectors live in signals.ts and
 * the file readers in analyze.ts; this file is the single list the docs, the
 * runner's titles and the tests all read.
 */
import type { AgentFindingType, AgentRuleFamily, AgentSeverity } from "./types.js";

export interface AgentRule {
  id: string;
  family: AgentRuleFamily;
  title: string;
  severity: AgentSeverity;
  confidence: "high" | "medium" | "low";
  cwe: string | null;
  findingType: AgentFindingType;
  impact: string;
  fix: string;
}

const rule = (r: AgentRule) => r;

/**
 * The rule set's version. A receipt names it, so a clean result can be
 * reproduced later with the same rules. Bump it with any change to what a
 * rule matches, its severity or the list itself (semver: a new rule or a
 * wider match is a minor bump, a fix that only narrows a match a patch).
 * rules.test.ts fails when the catalogue changes without a bump.
 */
// DIVERGES FROM UPSTREAM (firewall audit B1, B2, I4, I5, I9, minor docker flags): rule set 1.2.0-fw
// adds ls-agent-unparsed-file, ls-agent-oversize-file, ls-agent-long-line,
// ls-agent-analysis-incomplete, ls-agent-auto-run-network, ls-agent-broad-allow,
// ls-agent-permissive-setting, ls-agent-plugin-source, ls-agent-env-preload and
// ls-agent-mcp-host-access. Upstream should take these rules.
export const RULES_VERSION = "1.2.0-fw";

